import fs from 'node:fs';import assert from 'node:assert/strict';import{createClient}from'@supabase/supabase-js';import{buildProductGroups}from'../src/features/panol/stockGrupos.js';
process.loadEnvFile('.env');process.loadEnvFile('.env.backup.local');assert.equal(new URL(process.env.VITE_SUPABASE_URL).hostname,'fiwugzjeegzlgclfayfd.supabase.co');const db=createClient(process.env.VITE_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});const dir='backups/placas-antiruido-20261103',before=JSON.parse(fs.readFileSync(`${dir}/referencias-antes.json`)),id='985db2c6-6d36-472c-a504-63a10ac312a7',name='PLACAS ANTIRUIDO',special='9a9d026c-42fa-4330-94d9-fb0e984dfede';
async function read(q){const r=await q;if(r.error)throw Error(JSON.stringify(r.error));return r.data;}
const plan=[];const mat=before.panol_materiales[0];assert.equal(mat.id,id);const aliases=[mat.alias,mat.descripcion,'Antirruido metalizado sala maquinas'].filter(Boolean).join(' | ');plan.push({table:'panol_materiales',old:mat,patch:{descripcion:name,alias:aliases}});
for(const table of ['panol_obra_materiales_snapshot','panol_envio_items'])for(const old of before[table]){assert.ok(!old.material_id||old.material_id===id);assert.ok(!old.requisito_material_id||old.requisito_material_id===id);const patch={descripcion:name,material_id:id,requisito_material_id:id};if(table==='panol_obra_materiales_snapshot'&&old.id===special){const envio=before.panol_envio_items.find(x=>x.id===old.panol_envio_item_id);assert.equal(envio.estado,'recibido');assert.equal(envio.cantidad,'54');assert.equal(envio.unidad,'unidad');assert.equal(old.cantidad,40);assert.equal(old.unidad,'m2');assert.equal(old.cantidad_egresada,0);Object.assign(patch,{cantidad:54,unidad:'unidad',precio_unitario:envio.precio_unitario,moneda:envio.moneda,notas:[old.notas,'Corrección solicitada por Ezequiel 03/11/2026: PLACAS ANTIRUIDO. Se normaliza el saldo físico a 54 placas según el envío recibido 6d0120fb-3842-452d-b430-3ac9ef6c613b del 29/10/2026. El renglón original de matriz indicaba 40 m2; el pedido original conserva esa cantidad y unidad.'].filter(Boolean).join('\n')});}if(Object.entries(patch).some(([k,v])=>old[k]!==v))plan.push({table,old,patch});}
for(const old of before.purchase_request_items.filter(x=>x.material_id===id))plan.push({table:'purchase_request_items',old,patch:{description:name}});
fs.writeFileSync(`${dir}/plan.json`,JSON.stringify(plan,null,2),{flag:'wx'});const log=[];for(const p of plan){const current=await read(db.from(p.table).select('*').eq('id',p.old.id).single());for(const k of Object.keys(p.patch))assert.deepEqual(current[k],p.old[k],`Concurrent edit ${p.table}.${k}`);let q=db.from(p.table).update(p.patch).eq('id',p.old.id);if(current.updated_at)q=q.eq('updated_at',current.updated_at);const changed=await read(q.select('*').single());for(const[k,v]of Object.entries(p.patch))assert.deepEqual(changed[k],v);log.push({table:p.table,id:p.old.id,patch:p.patch});fs.writeFileSync(`${dir}/aplicados.json`,JSON.stringify(log,null,2));}
const after={};for(const table of ['panol_materiales','panol_obra_materiales_snapshot','panol_envio_items','purchase_request_items'])after[table]=await read(db.from(table).select('*').in('id',before[table].map(x=>x.id)).order('id'));
for(const table of Object.keys(after))for(const old of before[table]){const a=after[table].find(x=>x.id===old.id);assert.ok(a);const p=plan.find(x=>x.table===table&&x.old.id===old.id)?.patch||{};for(const [k,v]of Object.entries(old)){if(k==='updated_at'||k in p)continue;assert.deepEqual(a[k],v,`Unexpected change ${table}.${old.id}.${k}`);}}
const groups=buildProductGroups(after.panol_obra_materiales_snapshot,'todas');assert.equal(groups.length,1);assert.equal(groups[0].total,138);assert.equal(groups[0].stockLibre,0);assert.equal(groups[0].stockReservado,138);const obras=JSON.parse(fs.readFileSync(`${dir}/obras.json`));const summary={nombresOriginales:4,gruposConSaldoAntes:3,renglonesStockYObra:55,renglonesSinVinculoAntes:before.panol_obra_materiales_snapshot.filter(x=>!x.material_id).length,actualizados:log.length,totalPlacas:groups[0].total,libres:groups[0].stockLibre,asignadas:groups[0].stockReservado,obras:groups[0].locations.filter(x=>x.available>0).map(x=>({obra:obras.find(o=>o.id===x.obraId)?.codigo,placas:x.available}))};fs.writeFileSync(`${dir}/despues.json`,JSON.stringify({after,summary},null,2));console.log(JSON.stringify(summary));
